import{_ as i,a0 as t,w as d,s,ao as l,I as c,x as a,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何使用Docker Machine部署Swarm集群 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Docker Machine部署Swarm集群 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Docker Machine部署Swarm集群 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Docker Machine部署Swarm集群 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150625 How to Provision Swarm Clusters using Docker Machine","title":"如何使用Docker Machine部署Swarm集群","tag":"201508","desc":""},"relativePath":"201508/20150625 How to Provision Swarm Clusters using Docker Machine.md","filePath":"[post].md"}'),m={name:"201508/20150625 How to Provision Swarm Clusters using Docker Machine.md"};function p(h,e,k,w,u,g){const r=t("Link");return d(),s("div",null,[e[13]||(e[13]=l(`<h1 id="如何使用docker-machine部署swarm集群" tabindex="-1">如何使用Docker Machine部署Swarm集群 <a class="header-anchor" href="#如何使用docker-machine部署swarm集群" aria-label="Permalink to “如何使用Docker Machine部署Swarm集群”">​</a></h1><p>大家好，今天我们来研究一下如何使用Docker Machine部署Swarm集群。Docker Machine提供了标准的Docker API 支持，所以任何可以与Docker守护进程进行交互的工具都可以使用Swarm来（透明地）扩增到多台主机上。Docker Machine可以用来在个人电脑、云端以及的数据中心里创建Docker主机。它为创建服务器，安装Docker以及根据用户设定来配置Docker客户端提供了便捷化的解决方案。我们可以使用任何驱动来部署swarm集群，并且swarm集群将由于使用了TLS加密具有极好的安全性。</p><p>下面是我提供的简便方法。</p><h3 id="_1-安装docker-machine" tabindex="-1">1. 安装Docker Machine <a class="header-anchor" href="#_1-安装docker-machine" aria-label="Permalink to “1. 安装Docker Machine”">​</a></h3><p>Docker Machine 在各种Linux系统上都支持的很好。首先，我们需要从Github上下载最新版本的Docker Machine。我们使用curl命令来下载最先版本Docker Machine ie 0.2.0。</p><p>64位操作系统：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p>32位操作系统：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下载了最先版本的Docker Machine之后，我们需要对 /usr/local/bin/ 目录下的docker-machine文件的权限进行修改。命令如下：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>在做完上面的事情以后，我们要确保docker-machine已经安装正确。怎么检查呢？运行<code>docker-machine -v</code>指令，该指令将会给出我们系统上所安装的docker-machine版本。</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="Installing Docker Machine"></p><p>为了让Docker命令能够在我们的机器上运行，必须还要在机器上安装Docker客户端。命令如下。</p><pre><code># curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
# chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-创建machine" tabindex="-1">2. 创建Machine <a class="header-anchor" href="#_2-创建machine" aria-label="Permalink to “2. 创建Machine”">​</a></h3><p>在将Docker Machine安装到我们的设备上之后，我们需要使用Docker Machine创建一个machine。在这篇文章中，我们会将其部署在Digital Ocean Platform上。所以我们将使用“digitalocean”作为它的Driver API，然后将docker swarm运行在其中。这个Droplet会被设置为Swarm主控节点，我们还要创建另外一个Droplet，并将其设定为Swarm节点代理。</p><p>创建machine的命令如下：</p><pre><code># docker-machine create --driver digitalocean --digitalocean-access-token &lt;API-Token&gt; linux-dev
</code></pre><p><strong>备注</strong>： 假设我们要创建一个名为“linux-dev”的machine。<code>&lt;API-Token&gt;</code>是用户在Digital Ocean Cloud Platform的Digital Ocean控制面板中生成的密钥。为了获取这个密钥，我们需要登录我们的Digital Ocean控制面板，然后点击API选项，之后点击Generate New Token，起个名字，然后在Read和Write两个选项上打钩。之后我们将得到一个很长的十六进制密钥，这个就是<code>&lt;API-Token&gt;</code>了。用其替换上面那条命令中的API-Token字段。</p><p>现在，运行下面的指令，将Machine 的配置变量加载进shell里。</p><pre><code># eval &quot;$(docker-machine env linux-dev)&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-digitalocean-cloud.png" alt="Docker Machine Digitalocean Cloud"></p><p>然后，我们使用如下命令将我们的machine标记为ACTIVE状态。</p><pre><code># docker-machine active linux-dev
</code></pre><p>现在，我们检查它（指machine）是否被标记为了 ACTIVE &quot;*&quot;。</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-active-list.png" alt="Docker Machine Active List"></p><h3 id="_3-运行swarm-docker镜像" tabindex="-1">3. 运行Swarm Docker镜像 <a class="header-anchor" href="#_3-运行swarm-docker镜像" aria-label="Permalink to “3. 运行Swarm Docker镜像”">​</a></h3><p>现在，在我们创建完成了machine之后。我们需要将swarm docker镜像部署上去。这个machine将会运行这个docker镜像，并且控制Swarm主控节点和从节点。使用下面的指令运行镜像：</p><pre><code># docker run swarm create
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-create.png" alt="Docker Machine Swarm Create"></p><p>如果你想要在<strong>32位操作系统</strong>上运行swarm docker镜像。你需要SSH登录到Droplet当中。</p><pre><code># docker-machine ssh
#docker run swarm create
#exit
</code></pre><h3 id="_4-创建swarm主控节点" tabindex="-1">4. 创建Swarm主控节点 <a class="header-anchor" href="#_4-创建swarm主控节点" aria-label="Permalink to “4. 创建Swarm主控节点”">​</a></h3><p>在我们的swarm image已经运行在machine当中之后，我们将要创建一个Swarm主控节点。使用下面的语句，添加一个主控节点。</p><pre><code># docker-machine create \\
-d digitalocean \\
--digitalocean-access-token &lt;DIGITALOCEAN-TOKEN&gt;
--swarm \\
--swarm-master \\
--swarm-discovery token://&lt;CLUSTER-ID&gt; \\
swarm-master
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-master-create.png" alt="Docker Machine Swarm Master Create"></p><h3 id="_5-创建swarm从节点" tabindex="-1">5. 创建Swarm从节点 <a class="header-anchor" href="#_5-创建swarm从节点" aria-label="Permalink to “5. 创建Swarm从节点”">​</a></h3><p>现在，我们将要创建一个swarm从节点，此节点将与Swarm主控节点相连接。下面的指令将创建一个新的名为swarm-node的droplet，其与Swarm主控节点相连。到此，我们就拥有了一个两节点的swarm集群了。</p><pre><code># docker-machine create \\
-d digitalocean \\
--digitalocean-access-token &lt;DIGITALOCEAN-TOKEN&gt;
--swarm \\
--swarm-discovery token://&lt;TOKEN-FROM-ABOVE&gt; \\
swarm-node
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-nodes.png" alt="Docker Machine Swarm Nodes"></p><h3 id="_6-与swarm主控节点连接" tabindex="-1">6. 与Swarm主控节点连接 <a class="header-anchor" href="#_6-与swarm主控节点连接" aria-label="Permalink to “6. 与Swarm主控节点连接”">​</a></h3><p>现在，我们连接Swarm主控节点以便我们可以依照需求和配置文件在节点间部署Docker容器。运行下列命令将Swarm主控节点的Machine配置文件加载到环境当中。</p><pre><code># eval &quot;$(docker-machine env --swarm swarm-master)&quot;
</code></pre><p>然后，我们就可以跨节点地运行我们所需的容器了。在这里，我们还要检查一下是否一切正常。所以，运行<strong>docker info</strong>命令来检查Swarm集群的信息。</p><pre><code># docker info
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们可以用Docker Machine轻而易举地创建Swarm集群。这种方法有非常高的效率，因为它极大地减少了系统管理员和用户的时间消耗。在这篇文章中，我们以Digital Ocean作为驱动，通过创建一个主控节点和一个从节点成功地部署了集群。其他类似的驱动还有VirtualBox，Google Cloud Computing，Amazon Web Service，Microsoft Azure等等。这些连接都是通过TLS进行加密的，具有很高的安全性。如果你有任何的疑问，建议，反馈，欢迎在下面的评论框中注明以便我们可以更好地提高文章的质量！</p><hr>`,51)),c("p",null,[e[1]||(e[1]=a("via: ",-1)),o(r,{href:"http://linoxide.com/linux-how-to/provision-swarm-clusters-using-docker-machine/"},{default:n(()=>[...e[0]||(e[0]=[a("http://linoxide.com/linux-how-to/provision-swarm-clusters-using-docker-machine/",-1)])]),_:1})]),c("p",null,[e[5]||(e[5]=a("作者：",-1)),o(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[a("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),o(r,{href:"https://github.com/DongShuaike"},{default:n(()=>[...e[3]||(e[3]=[a("DongShuaike",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),c("p",null,[e[10]||(e[10]=a("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创翻译，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const M=i(m,[["render",p]]);export{x as __pageData,M as default};
